<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import DataTable from '@/components/zs/DataTable.vue';import Toolbar from '@/components/zs/Toolbar.vue';import SearchInput from '@/components/zs/SearchInput.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import SidePanel from '@/components/zs/SidePanel.vue';import ConfirmDialog from '@/components/zs/ConfirmDialog.vue';import Field from '@/components/zs/Field.vue';import ZButton from '@/components/zs/ZButton.vue';import Pagination from '@/components/zs/Pagination.vue';import {useCrmData} from '@/composables/useCrmData';import type {CrmCompany} from '@/types/crm';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Companies','CRM company accounts and relationship status.');const d=useCrmData(),router=useRouter(),q=ref(''),status=ref('All statuses'),page=ref(1),open=ref(false),editing=ref<CrmCompany|null>(null),remove=ref<CrmCompany|null>(null);const columns=[{key:'name',header:'Company'},{key:'industry',header:'Industry'},{key:'website',header:'Website'},{key:'primaryContact',header:'Primary contact'},{key:'phone',header:'Phone'},{key:'status',header:'Lead status'},{key:'owner',header:'Owner'},{key:'lastActivity',header:'Last activity'},{key:'actions',header:'',align:'right' as const}];const filtered=computed(()=>(d.companies.data.value??[]).filter(x=>(status.value==='All statuses'||x.status===status.value)&&`${x.name} ${x.industry}`.toLowerCase().includes(q.value.toLowerCase())));const rows=computed(()=>filtered.value.slice((page.value-1)*6,page.value*6));function edit(x?:CrmCompany){editing.value=x?structuredClone(x):{id:'new',companyId:d.activeCompanyId.value,name:'',industry:'',website:'',primaryContact:'',phone:'',email:'',status:'Prospect',owner:'',lastActivity:'',size:'',revenue:'',address:'',source:''};open.value=true}</script>
<template><AppShell><PageHeader title="Companies" :description="`${filtered.length} accounts in this company`"><template #actions><ZButton @click="edit()">Add company</ZButton></template></PageHeader><Panel><Toolbar><SearchInput v-model="q" placeholder="Search company or industry"/><select v-model="status" class="field max-w-44"><option>All statuses</option><option>Active</option><option>Prospect</option></select></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="1200"><template #name="{row}"><button class="font-medium text-primary hover:underline" @click="router.push(`/crm/companies/${row.id}`)">{{row.name}}</button></template><template #website="{row}"><span class="text-xs">{{row.website.replace('https://','')}}</span></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><div class="flex justify-end gap-1"><ZButton variant="ghost" @click="router.push(`/crm/companies/${row.id}`)">View</ZButton><ZButton variant="ghost" @click="edit(row)">Edit</ZButton><ZButton variant="ghost" @click="remove=row">Delete</ZButton></div></template><template #footer><Pagination :page="page" :pages="Math.ceil(filtered.length/6)" :total="filtered.length" @change="page=$event"/></template></DataTable></Panel><SidePanel :open="open" :title="editing?.id==='new'?'Add company':'Edit company'" description="Frontend preview; saving will connect to the CRM API." @close="open=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="open=false"><Field v-if="editing" v-model="editing.name" label="Company name" required/><Field v-if="editing" v-model="editing.website" label="Website" required/><Field v-if="editing" v-model="editing.industry" label="Industry" required/><Field v-if="editing" v-model="editing.size" label="Company size"/><Field v-if="editing" v-model="editing.revenue" label="Revenue"/><Field v-if="editing" v-model="editing.phone" label="Phone"/><Field v-if="editing" v-model="editing.email" label="Email" type="email"/><Field v-if="editing" v-model="editing.owner" label="Owner" required/><label class="block sm:col-span-2"><span class="label-caps">Address</span><textarea v-if="editing" v-model="editing.address" class="field mt-1.5 min-h-20"></textarea></label><ZButton type="submit">Save company</ZButton></form></SidePanel><ConfirmDialog :open="!!remove" title="Delete company?" message="This preview action removes no persistent records." confirm-label="Delete" tone="danger" @cancel="remove=null" @confirm="remove=null"/></AppShell></template>
